  const omm = inspect(byName[ORACLE.names['mmexport1759462512000.jpg']].data)
  assert(omm.tags['ExifIFD:9003'] === ORACLE.mmLocal && omm.tags['ExifIFD:9011'] === ORACLE.defTz, `微信图新建 EXIF：${omm.tags['ExifIFD:9003']} ${omm.tags['ExifIFD:9011']}`)
  const opng = inspect(byName[ORACLE.names['截屏2025-10-03 下午3.41.12.png']].data)
  assert(!opng.badCrc && opng.kinds.indexOf('eXIf') >= 0 && opng.kinds.indexOf('eXIf') < opng.kinds.indexOf('IDAT'), `PNG 新 eXIf 在 IDAT 前且 CRC 全对：${opng.kinds}`)
  assert(opng.tags['ExifIFD:9003'] === ORACLE.pngLocal, `PNG 补时间 ${opng.tags['ExifIFD:9003']}`)
  const gp = gpsDec(opng.tags); near(gp.lat, ORACLE.man.lat, 1e-9, 'PNG 手动坐标纬度'); near(gp.lon, ORACLE.man.lon, 1e-9, 'PNG 手动坐标经度')
  const opano = inspect(byName[ORACLE.names['pano.webp']].data), gpn = gpsDec(opano.tags)
