  near(gpn.lat, ORACLE.sydney.lat, 1e-9, '悉尼纬度'); near(gpn.lon, ORACLE.sydney.lon, 1e-9, '悉尼经度')
  assert(opano.riffOk && (opano.vp8xFlags & 0x08), 'WebP 改写后 RIFF 长度正确、VP8X 标着有 EXIF')
  for (const f of ['IMG_4120.HEIC', 'IMG_4102.JPG']) {
    assert(Buffer.compare(Buffer.from(byName[ORACLE.names[f]].data), Buffer.from(ORACLE.files[f], 'base64')) === 0, `${f} 只改名，字节应与原文件完全一致`)
  }

  // ⑧ 隐私：分享前清理
