  await page.waitForFunction(() => document.getElementById('ex-pv-on').checked && document.querySelector('#ex-pv-presets [data-p="share"]').getAttribute('aria-pressed') === 'true')
  const pk = await page.evaluate(() => ['ex-pv-k-gps', 'ex-pv-k-serial', 'ex-pv-k-leak'].map((id) => +document.querySelector('#' + id + ' b').textContent))
  assert(pk[0] === ORACLE.counts.gps && pk[1] === ORACLE.counts.serial, `隐私统计：定位 ${pk[0]}（应 ${ORACLE.counts.gps}）、序列号 ${pk[1]}（应 ${ORACLE.counts.serial}）`)
  await page.waitForFunction(() => +document.querySelector('#ex-pv-k-leak b').textContent === 1, null, { timeout: 10000 })
